Fixes: 3935ccc14d2c ("mwifiex: add cfg80211 testmode support")
Signed-off-by: YueHaibing <yuehaibing@huawei.com>
Signed-off-by: Kalle Valo <kvalo@codeaurora.org>

Here is the root cause:
The bug is caused by the lack of proper memory management for the `hostcmd` variable, which is allocated using `kzalloc`. In the original code, if any error occurs during the processing of the command or the response handling, the allocated memory for `hostcmd` is not freed, leading to a memory leak.

Here is the patch:

 static int mwifiex_tm_cmd(struct wiphy *wiphy, struct wireless_dev *wdev,
 			  void *data, int len)
 {
 	struct mwifiex_private *priv = mwifiex_netdev_get_priv(wdev->netdev);
 	struct mwifiex_ds_misc_cmd *hostcmd;
 	struct nlattr *tb[MWIFIEX_TM_ATTR_MAX + 1];
 	struct sk_buff *skb;
 	int err;

 	if (!priv)
 		return -EINVAL;

 	err = nla_parse(tb, MWIFIEX_TM_ATTR_MAX, data, len, mwifiex_tm_policy,
 			NULL);
 	if (err)
 		return err;

 	if (!tb[MWIFIEX_TM_ATTR_CMD])
 		return -EINVAL;

 	switch (nla_get_u32(tb[MWIFIEX_TM_ATTR_CMD])) {
 	case MWIFIEX_TM_CMD_HOSTCMD:
 		if (!tb[MWIFIEX_TM_ATTR_DATA])
 			return -EINVAL;

 		hostcmd = kzalloc(sizeof(*hostcmd), GFP_KERNEL);
 		if (!hostcmd)
 			return -ENOMEM;

 		hostcmd->len = nla_len(tb[MWIFIEX_TM_ATTR_DATA]);
 		memcpy(hostcmd->cmd, nla_data(tb[MWIFIEX_TM_ATTR_DATA]),
 		       hostcmd->len);

 		if (mwifiex_send_cmd(priv, 0, 0, 0, hostcmd, true)) {
 			dev_err(priv->adapter->dev, "Failed to process hostcmd\n");
+			kfree(hostcmd);
 			return -EFAULT;
 		}

 		/* process hostcmd response*/
 		skb = cfg80211_testmode_alloc_reply_skb(wiphy, hostcmd->len);
-		if (!skb)
+		if (!skb) {
+			kfree(hostcmd);
 			return -ENOMEM;
+		}
 		err = nla_put(skb, MWIFIEX_TM_ATTR_DATA,
 			      hostcmd->len, hostcmd->cmd);
 		if (err) {
+			kfree(hostcmd);
 			kfree_skb(skb);
 			return -EMSGSIZE;
 		}

 		err = cfg80211_testmode_reply(skb);
 		kfree(hostcmd);
 		return err;
 	default:
 		return -EOPNOTSUPP;
 	}
 }
 #endif


